Suppose that Assumptions~assump:smooth -- assump:stepsize-twotime, assump:noise-fclt and assump:mart-decouple-rate hold.
For each $n$, define the following filtrations
\begin{align}
	\begin{split}
	{\mathcal F}^{\bar{\textnormal{X}}}_{n,t} & = \begin{cases}
		{\mathcal F}_{n}, &  t = 0; \\
		{\mathcal F}_{m+1}, & t \in \left( \sum_{i=n}^{m-1} \alpha_{i}, \sum_{i=n}^{m} \alpha_{i} \right] \text{ for } m \ge n;
	\end{cases} \\
	{\mathcal F}^{\bar{\textnormal{Z}}}_{n,t} & = \begin{cases}
		{\mathcal F}_{n}, &  t = 0; \\
		{\mathcal F}_{m+1}, & t \in \left( \sum_{i=n}^{m-1} \beta_{i}, \sum_{i=n}^{m} \beta_{i} \right] \text{ for } m \ge n.
	\end{cases} 
	\end{split}
\end{align}

\begin{enumerate}[(i)]
    \item  For any $f \in C^2_c({\mathbb R}^{d_x})$ and $t \ge 0$, with ${\mathcal A}^x$ defined in (30), we have the following decomposition
    \begin{equation*}

    f({\bar{\textnormal{X}}}_{n}(t)) - f({\bar{\textnormal{X}}}_{n}(0)) - \int_0^{t} {\mathcal A}^x f({\bar{\textnormal{X}}}_{n}(s))\, \mathrm{d} s
    = {\mathcal M}_{n}^f(t) + {\mathcal R}_{n}^f(t), 
    \end{equation*}
    where for each $n$, ${\mathcal M}_{n}^f(t)$ is a martingale w.r.t. $({\mathcal F}^{\bar{\textnormal{X}}}_{n,t} )_{t \ge 0}$ and for each $t$, ${\mathbb E} | {\mathcal R}_{n}^f(t) | \to 0$ as $n \to \infty$. 
    \item For any $g \in C^2_c({\mathbb R}^{d_y})$ and $t \ge 0$, with ${\mathcal A}^y$ defined in (31), we have the following decomposition
    \begin{equation*}

    g({\bar{\textnormal{Z}}}_{n}(t)) - g({\bar{\textnormal{Z}}}_{n}(0)) - \int_0^{t} {\mathcal A}^y f({\bar{\textnormal{Z}}}_{n}(s))\, \mathrm{d} s
    = {\mathcal M}_{n}^g(t) + {\mathcal R}_{n}^g(t), 
    \end{equation*}
    where for each $n$, ${\mathcal M}_{n}^g(t)$ is a martingale w.r.t. $( {\mathcal F}^{\bar{\textnormal{Z}}}_{n,t})_{t \ge 0}$ and for each $t$, ${\mathbb E} | {\mathcal R}_{n}^g(t) | \to 0$ as $n \to \infty$.
\end{enumerate}

Suppose that Assumptions~assump:smooth -- assump:noise-fclt and assump:mart-decouple-rate hold.
	\begin{enumerate}[(i)]
		\item  The stochastic process ${\bar{\textnormal{X}}}_{n}(\cdot)$ defined in (12) converges weakly to the stationary solution of the following SDE 
		\begin{equation}
			d {\textnormal{X}}(t) = - B_1 {\textnormal{X}}(t) dt + \Sigma_{\xi}^{1/2} d {\textnormal{W}}^{d_x}(t).
		\end{equation}
		The rescaled iterate $ {\check{x}}_{n} $ defined in (11) converges weakly to the invariant distribution of (14), i.e., ${\mathcal N}(0, \Sigma_x)$, where $\Sigma_x$ satisfies the following Lyapunov equation 
		\begin{equation}
			B_1 \Sigma_x + \Sigma_x B_1 = \Sigma_{\xi}.
		\end{equation}





		\item  The stochastic process ${\bar{\textnormal{Y}}}_{n}(\cdot)$ defined in (13) converges weakly to the stationary solution of the following SDE 
		\begin{equation}
			d {\textnormal{Y}}(t) = - \left(B_3 - \frac{\tilde{\beta} {I}}{2}  \right) {\textnormal{Y}}(t) dt + \widetilde{\Sigma}_{\psi}^{1/2} d {\textnormal{W}}^{d_y}(t),
		\end{equation}
		where the matrix $\widetilde{\Sigma}_{\psi}$ is defined as 
		\begin{equation}
			\widetilde{\Sigma}_{\psi} := \Sigma_{\psi} - B_2 B_1^{-1} \Sigma_{\xi,\psi} - \Sigma_{\xi, \psi}^\top B_1^{-\top} B_2^\top + B_2 B_1^{-1} \Sigma_{\xi} B_1^{-\top} B_2^\top.
		\end{equation}
		The rescaled iterate $ {\check{y}}_{n}$ defined in (11) converges weakly to the invariant distribution of (16), i.e., ${\mathcal N}(0, \Sigma_y)$, where $\Sigma_y$ satisfies the following Lyapunov equation
		\begin{equation}
			\left(B_3 - \frac{\tilde{\beta} {I}}{2} \right) \Sigma_y + \Sigma_y \left( B_3 - \frac{\tilde{\beta} {I}}{2} \right) = \widetilde{\Sigma}_{\psi}.
		\end{equation}
	\end{enumerate}
